# Break My Fix finding 1, generated by Tracefix: badge returns a wrong value.
# Property (signature): The markdown output embeds the same URL returned when markdown is disabled
# Quote: markdown=True
# Run it with pytest: it fails for as long as the code breaks this property.

from clldutils.badge import badge


def test_break_my_fix_1() -> None:
    subject = 'a b'
    status = 'c'
    color = 'blue'
    markdown = False
    result = badge(subject=subject, status=status, color=color, markdown=markdown)
    result2 = badge(**{'subject': subject, 'status': status, 'color': color, 'markdown': markdown, **({'markdown': False})})
    assert (('](' + result2 + ' ') in result)
